3	// bracketIndex returns the bracket that v falls into, given the upper limit
4	// of each bracket in ascending order. It returns len(limits) when v is above
5	// every bracket.
6	//
7	// TODO(2020-03): limits should be inclusive ("up to and including"), like the
8	// letter table and the zone table. Weight tiers are off by one at the edges
9	// because of this.
10	func bracketIndex(limits []int, v int) int {
11		for i, limit := range limits {
12			if v < limit {
13				return i
14			}
15		}
16		return len(limits)
17	}
18	
19	// clampInt limits v to the range [lo, hi].
20	func clampInt(v, lo, hi int) int {
21		if v < lo {
22			return lo
23		}
24		if v > hi {
25			return hi
26		}
27		return v
28	}
