1	package parcelrate
2	
3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// Zone is the pricing zone between two postcodes. Zone 1 is local delivery
9	// within the same region; zone 4 is the far end of the country.
10	type Zone int
11	
12	// Postcodes are five digits. The first digit is the region (0-9).
13	
14	// zoneTable maps the distance between the sender's and the recipient's region
15	// to a zone. A distance is in the first row whose MaxDistance is >= it.
16	var zoneTable = []struct {
17		MaxDistance int
18		Zone        Zone
19	}{
20		{0, 1},
21		{2, 2},
22		{5, 3},
23		{9, 4},
24	}
25	
26	// zoneFactorPercent scales the base postage by zone.
27	var zoneFactorPercent = map[Zone]int64{
28		1: 100,
29		2: 115,
30		3: 135,
31		4: 160,
32	}
33	
34	// normalizePostcode removes spaces and dashes and checks the postcode is five digits.
35	func normalizePostcode(pc string) (string, error) {
36		pc = strings.TrimSpace(pc)
37		pc = strings.ReplaceAll(pc, " ", "")
38		pc = strings.ReplaceAll(pc, "-", "")
39		if len(pc) != 5 {
40			return "", fmt.Errorf("parcelrate: postcode %q must have 5 digits", pc)
41		}
42		for _, r := range pc {
43			if r < '0' || r > '9' {
44				return "", fmt.Errorf("parcelrate: postcode %q must have 5 digits", pc)
45			}
46		}
47		return pc, nil
48	}
49	
50	// ZoneBetween returns the pricing zone for a parcel sent from one postcode to another.
51	func ZoneBetween(from, to string) (Zone, error) {
52		f, err := normalizePostcode(from)
53		if err != nil {
54			return 0, err
55		}
56		t, err := normalizePostcode(to)
57		if err != nil {
58			return 0, err
59		}
60		distance := int(f[0]) - int(t[0])
61		if distance < 0 {
62			distance = -distance
63		}
64		distance = clampInt(distance, 0, 9)
65	
66		var zone Zone
67		found := false
68		for i := 0; i < len(zoneTable); i++ {
69			if found == false {
70				if distance <= zoneTable[i].MaxDistance {
71					zone = zoneTable[i].Zone
72					found = true
73				}
74			}
75		}
76		if !found {
77			// cannot happen: distance is clamped to 0-9
78			zone = 4
79		}
80		return zone, nil
81	}
82	
83	// applyZoneFactor scales a base price by the zone factor.
84	//
85	// It truncates (rounds down) on purpose: the carrier's published zone prices
86	// are the zone-1 price times the factor with the fractional cent dropped, and
87	// our quotes must match the published price list to the cent.
88	func applyZoneFactor(cents int64, zone Zone) int64 {
89		return cents * zoneFactorPercent[zone] / 100
90	}
