1	package parcelrate
2	
3	import "fmt"
4	
5	// Letters and large letters are priced by weight only, with no zones or surcharges.
6	
7	type letterTier struct {
8		upTo  int // grams, inclusive
9		price int64
10	}
11	
12	var letterTiers = []letterTier{
13		{upTo: 20, price: 85},
14		{upTo: 100, price: 140},
15		{upTo: 250, price: 210},
16		{upTo: 500, price: 330},
17	}
18	
19	var largeLetterTiers = []letterTier{
20		{upTo: 100, price: 190},
21		{upTo: 250, price: 260},
22		{upTo: 500, price: 380},
23		{upTo: 750, price: 450},
24	}
25	
26	// maxLetterThicknessMm is the thickest item accepted as a (large) letter.
27	const maxLetterThicknessMm = 25
28	
29	// LetterPostage returns the price of a letter weighing grams. Large letters are
30	// items thicker than 5 mm. Items thicker than 25 mm must go as parcels.
31	func LetterPostage(grams int, thicknessMm int) (int64, error) {
32		if grams <= 0 {
33			return 0, fmt.Errorf("%w: letter weight must be positive", ErrInvalidParcel)
34		}
35		if thicknessMm > maxLetterThicknessMm {
36			return 0, fmt.Errorf("%w: %d mm is too thick for a letter, send it as a parcel", ErrOversize, thicknessMm)
37		}
38		tiers := letterTiers
39		if thicknessMm > 5 {
40			tiers = largeLetterTiers
41		}
42		// NOTE: this is the same lookup as bracketIndex in brackets.go; could reuse it.
43		for i := 0; i < len(tiers); i++ {
44			if grams <= tiers[i].upTo {
45				return tiers[i].price, nil
46			}
47		}
48		return 0, fmt.Errorf("%w: %d g is too heavy for a letter", ErrTooHeavy, grams)
49	}
50	
51	// LetterPriceList renders the letter prices for the counter poster.
52	func LetterPriceList() string {
53		s := "Letters\n"
54		for _, t := range letterTiers {
55			s += fmt.Sprintf("up to %d g\t%s\n", t.upTo, centsToString(t.price))
56		}
57		s += "Large letters\n"
58		for _, t := range largeLetterTiers {
59			s += fmt.Sprintf("up to %d g\t%s\n", t.upTo, centsToString(t.price))
60		}
61		return s
62	}
63	
64	// centsToString formats cents as dollars.
65	func centsToString(c int64) string {
66		return fmt.Sprintf("$%.2f", float64(c)/100)
67	}
