9	func chargeNamed(q Quotation, prefix string) (Charge, bool) {
10		for _, c := range q.Charges {
11			if strings.HasPrefix(c.Name, prefix) {
12				return c, true
13			}
14		}
15		return Charge{}, false
16	}
