18	func TestQuoteLocalStandard(t *testing.T) {
19		p := Parcel{WeightGrams: 1200, LengthCm: 30, WidthCm: 20, HeightCm: 10}
20		q, err := Quote(p, "10115", "12045", Standard)
21		if err != nil {
22			t.Fatal(err)
23		}
24		if q.Zone != 1 || q.Grams != 1200 {
25			t.Errorf("zone=%d grams=%d, want zone 1, 1200 g", q.Zone, q.Grams)
26		}
27		want := []Charge{
28			{"Postage (Standard, up to 2000 g, zone 1)", 790},
29			{"Fuel surcharge", 95},
30		}
31		if len(q.Charges) != len(want) {
32			t.Fatalf("charges = %+v, want %+v", q.Charges, want)
33		}
34		for i := range want {
35			if q.Charges[i] != want[i] {
36				t.Errorf("charge %d = %+v, want %+v", i, q.Charges[i], want[i])
37			}
38		}
39		if q.TotalCents != 885 {
40			t.Errorf("total = %d, want 885", q.TotalCents)
41		}
